var import_dayjs4 = __toESM(require_dayjs_min(), 1);
class GlobalService {
  static async getStats(user3) {
    let userWhere = {};
    let locationWhere = {};
    if (user3.role !== "admin") {
      userWhere.villageId = user3.villageId;
      userWhere.role = { [Op.in]: ["umum"] };
      locationWhere.villageId = user3.villageId;
    }
    const [totalUsers, totalLocations, village, totalVillages] = await Promise.all([
      User.count({ where: userWhere }),
      Location.count({ where: locationWhere }),
      Village.findOne({ where: { id: user3.villageId } }),
      Village.count()
    ]);
    return {
      user_total: totalUsers,
      location_total: totalLocations,
      village_name: village?.name || "-",
      village_total: totalVillages
    };
  }
  static async getStatsPresence(query, user3) {
    const { start, end } = query;
    let startDate, endDate;
    let userWhere = {};
    if (!start || !end) {
      startDate = import_dayjs4.default().startOf("days");
      endDate = import_dayjs4.default().endOf("days");
    } else {
      startDate = import_dayjs4.default(start).startOf("days");
      endDate = import_dayjs4.default(end).endOf("days");
    }
    if (!startDate.isValid() || !endDate.isValid())
      throw ResponseError(400, "Format periode tidak valid. Gunakan format YYYY-MM atau YYYY-MM-DD.");
    if (user3.role !== "admin") {
      userWhere.villageId = user3.villageId;
      userWhere.role = { [Op.in]: ["umum"] };
    }
    const startOfYear = import_dayjs4.default().startOf("year").toDate();
    const endOfYear = import_dayjs4.default().endOf("year").toDate();
    const calendarController = new CalendarController;
    const workDays = await calendarController.workDays(start, end);
    const [totalUsers, presences, yearlyPresences] = await Promise.all([
      User.count({ where: userWhere }),
      Presence.findAll({
        where: {
          [Op.or]: [
            {
              in: {
                [Op.between]: [startDate.toDate(), endDate.toDate()]
              }
            },
            {
              out: {
                [Op.between]: [startDate.toDate(), endDate.toDate()]
              }
            }
          ]
        },
        include: [{
          model: User,
          required: true,
          where: userWhere
        }]
      }),
      Presence.findAll({
        attributes: ["in", "out", "status"],
        where: {
          [Op.or]: [
            {
              in: {
                [Op.between]: [startOfYear, endOfYear]
              }
            },
            {
              out: {
                [Op.between]: [startOfYear, endOfYear]
              }
            }
          ]
        },
        include: [{
          model: User,
          required: true,
          where: userWhere
        }]
      })
    ]);
    const users = await User.findAll({
      attributes: ["id"],
      where: userWhere
    });
    const presentUserIds = new Set;
    const onTimeUserIds = new Set;
    const lateUserIds = new Set;
    const cuti = new Set;
    const noKet = new Set;
    let terlambat_total = 0, hadir = 0;
    for (const p of presences) {
      const uId = p.userId;
      presentUserIds.add(uId);
      if (p.status == "terlambat" || p.status == "pulang") {
        lateUserIds.add(uId);
        terlambat_total++;
      } else if (p.status == "hadir") {
        onTimeUserIds.add(uId);
        hadir++;
      } else if (p.status == "cuti") {
        cuti.add(uId);
      } else {
        noKet.add(uId);
      }
    }
    const presence_total = presences.length;
    const presence_user_total = presentUserIds.size;
    const hadir_total = onTimeUserIds.size;
    const user_terlambat_total = lateUserIds.size;
    const cuti_total = cuti.size;
    const belum_absen_total = Math.max(0, totalUsers - presence_user_total);
    const presentase_hadir = workDays > 0 ? Number(((hadir + terlambat_total) / workDays * 100).toFixed(2)) : 0;
    let alpha_total = 0;
    users.forEach((data) => {
      const presence2 = presences.filter((p) => p.userId === data.id);
      const hadir2 = presence2.filter((p) => p.status === "hadir");
      const terlambat = presence2.filter((p) => p.status === "terlambat" || p.status === "pulang");
      const cuti2 = presence2.filter((p) => p.status === "cuti");
      alpha_total += Math.max(0, workDays - (hadir2.length + terlambat.length + cuti2.length));
    });
    const monthNames = [
      "Januari",
      "Februari",
      "Maret",
      "April",
      "Mei",
      "Juni",
      "Juli",
      "Agustus",
      "September",
      "Oktober",
      "November",
      "Desember"
    ];
    const presence_status = Array.from({ length: 12 }, (_2, i) => ({
      bulan: monthNames[i],
      tepat_waktu: 0,
      terlambat: 0
    }));
    for (const p of yearlyPresences) {
      const date2 = p.in || p.out;
      if (!date2)
        continue;
      const monthIndex = import_dayjs4.default(date2).month();
      if (monthIndex >= 0 && monthIndex < 12) {
        if (p.status === "terlambat" || p.status === "pulang") {
          presence_status[monthIndex].terlambat++;
        } else if (p.status === "hadir") {
          presence_status[monthIndex].tepat_waktu++;
        }
      }
    }
    return {
      presence_total,
      presence_user_total,
      hadir_total,
      user_terlambat_total,
      terlambat_total,
      cuti_total,
      belum_absen_total,
      alpha_total,
      presentase_hadir,
      presence_status
    };
  }
}

