// src/modules/village/service.ts
class VillageService {
  static async get(user3) {
    const whereClause = {};
    if (user3.role !== "admin") {
      if (!user3.villageId) {
        return [];
      }
      whereClause.id = user3.villageId;
    }
    const villages = await Village.findAll({
      where: whereClause,
      attributes: ["id", "name", "address"],
      include: [{
        model: SubDistrict,
        attributes: ["id", "name"],
        required: true
      }]
    });
    const result = await Promise.all(villages.map(async (v) => {
      const userCount = await User.count({ where: { villageId: v.id } });
      const locationCount = await Location.count({ where: { villageId: v.id } });
      return {
        id: v.id,
        name: v.name,
        address: v.address,
        subDistrict: v.SubDistrict,
        user_count: Number(userCount || 0),
        location_count: Number(locationCount || 0)
      };
    }));
    return result;
  }
  static async create(body, user3) {
    if (user3.role !== "admin") {
      throw ResponseError(403, "Akses ditolak");
    }
    const existingName = await Village.findOne({
      where: database_default.where(database_default.fn("lower", database_default.col("name")), body.name.toLowerCase())
    });
    if (existingName) {
      throw ResponseError(400, "Nama desa sudah digunakan");
    }
    const id = v4_default();
    const newVillage = await Village.create({
      id,
      name: body.name,
      address: body.address,
      subDistrictId: body.subDistrictId
    });
    return {
      id: newVillage.id,
      name: newVillage.name,
      address: newVillage.address,
      subDistrictId: newVillage.subDistrictId
    };
  }
  static async update(id, body, user3) {
    if (user3.role !== "admin") {
      throw ResponseError(403, "Akses ditolak");
    }
    const village = await Village.findByPk(id);
    if (!village) {
      throw ResponseError(404, "Desa tidak ditemukan");
    }
    const updateData = {};
    if (body.name !== undefined) {
      const existingName = await Village.findOne({
        where: {
          id: { [Op.ne]: id },
          [Op.and]: database_default.where(database_default.fn("lower", database_default.col("name")), body.name.toLowerCase())
        }
      });
      if (existingName) {
        throw ResponseError(400, "Nama desa sudah digunakan");
      }
      updateData.name = body.name;
    }
    if (body.address !== undefined) {
      updateData.address = body.address;
    }
    if (body.subDistrictId !== undefined) {
      updateData.subDistrictId = body.subDistrictId;
    }
    await village.update(updateData);
    return {
      id: village.id,
      name: village.name,
      address: village.address,
      subDistrictId: village.subDistrictId || null
    };
  }
  static async destroy(id, user3) {
    if (user3.role !== "admin") {
      throw ResponseError(403, "Akses ditolak");
    }
    const village = await Village.findByPk(id);
    if (!village) {
      throw ResponseError(404, "Desa tidak ditemukan");
    }
    const hasUser = await User.findOne({
      where: { villageId: id }
    });
    if (hasUser) {
      throw ResponseError(400, "Desa tidak dapat dihapus karena memiliki data pengguna");
    }
    const hasLocation = await Location.findOne({
      where: { villageId: id }
    });
    if (hasLocation) {
      throw ResponseError(400, "Desa tidak dapat dihapus karena memiliki data lokasi");
    }
    await Village.destroy({ where: { id } });
    return true;
  }
}

