// src/workers/presence.worker.ts
async function presenceWorker() {
  console.log("Presence worker started");
  while (true) {
    try {
      const delay = Number(process.env.WORKER_DELAY ?? "500");
      await new Promise((resolve) => setTimeout(resolve, delay));
      const result = await redis_default.brpop("presence", 1);
      if (!result)
        continue;
      const [, userId] = result;
      const payloadStr = await redis_default.rpop(`presence:${userId}`);
      if (!payloadStr)
        continue;
      const payload = JSON.parse(payloadStr);
      await PresenceController.presence(payload);
    } catch (error) {
      console.error(error);
    }
  }
}
var presence_worker_default = presenceWorker;

